def transform(grid):
    grid = np.asarray(grid)
    bg = background(grid)
    out = grid.copy()
    table = {1: 1, 2: 3, 3: 2, 4: 4}

    def holes(o):
        g = np.pad(o["grid"], 1, constant_values=bg)
        H, W = g.shape
        n = 0
        for c in components(g == bg):
            if not any(y in (0, H - 1) or x in (0, W - 1) for y, x in c):
                n += 1
        return n

    for o in objects(grid, bg=bg):
        h = holes(o)
        colour = table.get(h, h)
        for y, x in o["cells"]:
            out[y, x] = colour
        emit(out, f"Object with {h} enclosed hole(s) at bbox {o['box']} recoloured to {colour} (hole count -> colour table: 1->1, 2->3, 3->2, 4->4)")

    return out
